const order = $input.first().json;
const items = JSON.parse(order.body?.line_items || '[]');
const itemSummary = items.map(i => `${i.title} x${i.quantity}`).join(', ');
const totalWeight = items.reduce((sum, i) => sum + (i.grams || 0) * i.quantity, 0);

return [{
  json: {
    ...order,
    itemSummary: itemSummary || 'See order details',
    itemCount: items.length || 0,
    totalWeightGrams: totalWeight
  }
}];

const order = $input.first().json;
const label = {
  shipFrom: {
    name: 'Your Store Name',
    address: '123 Warehouse St',
    city: 'Your City',
    state: 'YS',
    zip: '12345',
    country: 'US'
  },
  shipTo: {
    name: order.customerName,
    address: order.shippingAddress,
    city: order.shippingCity,
    state: order.shippingState,
    zip: order.shippingZip,
    country: order.shippingCountry
  },
  package: {
    weightGrams: order.totalWeightGrams || 500,
    orderNumber: order.orderNumber,
    itemCount: order.itemCount
  },
  generatedAt: new Date().toISOString()
};

return [{ json: { ...order, shippingLabel: label } }];
